mkdir -p ttmp/2026/11/26/IRWB-023-B--exact-parallel-folds-for-tix/scripts/00-probe && cat > ttmp/2026/11/26/IRWB-023-B--exact-parallel-folds-for-tix/scripts/00-probe/main.cu <<'EOF'
#include <cuda_runtime.h>
#include <cstdio>
__global__ void probe(unsigned *bits) {
  int lane = threadIdx.x;
  float x = __fadd_rn(1.0f, 0x1p-24f);
  unsigned next = __shfl_sync(0xffffffffu, __float_as_uint(x), 0);
  if (lane == 31) *bits = next;
}
int main() {
  unsigned *p, word = 0;
  cudaDeviceProp d;
  if (cudaGetDeviceProperties(&d,0) || cudaMalloc(&p,sizeof(word))) return 1;
  probe<<<1,32>>>(p);
  if (cudaMemcpy(&word,p,sizeof(word),cudaMemcpyDeviceToHost)) return 2;
  printf("%s sm_%d%d tie %08x
",d.name,d.major,d.minor,word);
  return word != 0x3f800000u;
}
EOF
node tools/cuda-remote.mjs ttmp/2026/11/26/IRWB-023-B--exact-parallel-folds-for-tix/scripts/00-probe

python3 - <<'PY'
from pathlib import Path
p=Path('ttmp/2026/11/26/IRWB-023-B--exact-parallel-folds-for-tix/scripts/09-plan-gate.mjs')
s=p.read_text().replace("import assert from 'node:assert/strict';","import assert from 'node:assert/strict';
import {inspectRow} from './12-row-region.mjs';")
a=s.index('const eq=')
b=s.index('function verifyReceipt',a)
s=s[:a]+'''function verifyRows(module,chosen) {
  const fn=module.functions.find(f=>f.name===chosen);
  if(fn?.params.length!==1 || fn.statements.length!==4) return 'function signature or statement count';
  const region=inspectRow(fn,0);
  if(region.error) return region.error;
  if(fn.result!==region.output) return 'returned tensor';
}
'''+s[b:]
p.write_text(s)
PY
node ttmp/2026/11/26/IRWB-023-B--exact-parallel-folds-for-tix/scripts/09-plan-gate.mjs calibrated > ttmp/2026/11/26/IRWB-023-B--exact-parallel-folds-for-tix/scripts/09-calibrated.jsonl
